+    `[candidate=${candidate.id} ticket=${scope.number} state=${scope.state}]`,
+    `ticket: #${scope.number} ${scope.title}`,
+    "stated scope:",
+    clip(scope.body.trimEnd(), MAX_TICKET_BODY_CHARS),
+    "work done in this ticket's session(s):",
+    ...describeWork(candidate),
